// Build image from Dockerfile in current directory
docker build -t order-service:v1 .

// Run container with port mapping
docker run -d -p 8080:8080 --name order-api order-service:v1

// List running containers
docker ps

// View real-time logs
docker logs -f order-api

// Open shell inside running container for debugging
docker exec -it order-api /bin/bash

// Stop container
docker stop order-api

// Remove stopped container
docker rm order-api

// List all images
docker images

// Remove image
docker rmi order-service:v1

// Standard mapping: same port inside and outside
docker run -d -p 8080:8080 --name order-api order-service:v1
// Access at http://localhost:8080

// Conflict resolution: map different host port
docker run -d -p 9090:8080 --name payment-api payment-service:v1
// Container listens on 8080, but access at http://localhost:9090

// Multiple port mappings for same container
docker run -d -p 8080:8080 -p 5005:5005 --name order-api order-service:v1
// 8080 for HTTP, 5005 for Java debugger

// Bind to specific network interface
docker run -d -p 127.0.0.1:8080:8080 --name internal-api order-service:v1
// Only accessible from localhost, not from network

// Let Docker assign random host port
docker run -d -p 8080 --name temp-api order-service:v1
// Use docker ps to see which port Docker chose

// View all logs from container
docker logs order-api

// Follow logs in real time (essential during development)
docker logs -f order-api

// See only last 50 lines (avoid scrolling through startup messages)
docker logs --tail 50 order-api

// View logs from last 10 minutes
docker logs --since 10m order-api

// Combine flags for targeted debugging
docker logs --since 5m --tail 100 -f order-api

// Filter logs with grep for specific errors
docker logs order-api | grep ERROR

// View logs with timestamps
docker logs -t order-api

// Save logs to file for analysis
docker logs order-api > order-api-logs.txt

// Check Docker disk usage first
docker system df

// Remove all stopped containers, unused networks, dangling images, and build cache
docker system prune

// More aggressive: include unused images (not just dangling)
docker system prune -a

// Remove only stopped containers
docker container prune

// Remove only unused images
docker image prune

// Remove specific container
docker rm order-api

// Remove specific image
docker rmi order-service:v1

// Remove all stopped containers (manual approach)
docker rm $(docker ps -a -q -f status=exited)

// Force remove running container
docker rm -f order-api

// Remove image even if containers reference it
docker rmi -f order-service:v1

// Step 1: Check application logs
docker logs --tail 100 -f order-api

// Step 2: Open shell inside running container
docker exec -it order-api /bin/bash

// Inside container: check if config file exists
ls -la /app/config/

// Inside container: verify environment variables
env | grep DATABASE

// Inside container: test network connectivity
curl http://localhost:8080/actuator/health

// Step 3: Inspect container configuration
docker inspect order-api

// Filter inspect output for specific info (environment variables)
docker inspect -f '{{.Config.Env}}' order-api

// Monitor real-time resource usage
docker stats order-api

// See running processes inside container
docker top order-api
